"""Run the cross-built shell and compile parsers generated by cross-built yacc."""

import json
from pathlib import Path
import re
import sys

from guest import files_guest


qemu, image, rc, yacc, output = sys.argv[1:]
here = Path(__file__).parent
yacc = Path(yacc)
fixtures = {
    "rc": rc,
    "rc-check": here / "cross-rc.rc",
    "yacc": yacc / "bin/yacc",
    "parser.y": here / "yacc/parser.y",
    **{name: yacc / "share/yacc" / name for name in ("yaccpar", "yaccpars")},
}
with files_guest(qemu, image, fixtures) as guest:
    guest.command("chmod +x /tmp/rc /tmp/yacc; cd /tmp; RC_TEST=inherited")
    guest.command("/tmp/rc /tmp/rc-check", "cross-rc-PASS")
    for command in ("exit deliberate", "if("):
        result = guest.command(f"/tmp/rc -c '{command}'; echo RC-STATUS:$status")
        if not re.search(r"(?m)^RC-STATUS:.+$", result):
            raise RuntimeError(f"rc lost failure status: {result}")
    for name in ("yaccpar", "yaccpars"):
        guest.command(f"bind /tmp/{name} /sys/lib/{name}")
    guest.command("/tmp/yacc -d parser.y")
    guest.command("6c y.tab.c && 6l -o parser y.tab.6")
    guest.command("./parser '20+22'", "42")
    guest.command("./parser '3+4+5'", "12")
    result = guest.command("./parser '2+'; echo PARSER-STATUS:$status")
    if not re.search(r"(?m)^PARSER-STATUS:.+$", result):
        raise RuntimeError(f"parser accepted invalid input: {result}")
    guest.command("/tmp/yacc -S -o alternate.c parser.y && test -s alternate.c")
    guest.command("echo '%%' > invalid.y")
    result = guest.command("/tmp/yacc invalid.y; echo YACC-STATUS:$status")
    if not re.search(r"(?m)^YACC-STATUS:.+$", result):
        raise RuntimeError(f"yacc accepted invalid grammar: {result}")
Path(output).mkdir()
Path(output, "results.json").write_text(json.dumps({
    "rc": "quoting, functions, lists, loops, pipes, environment, nested shells and failure status passed",
    "yacc": "parser execution, alternate skeleton generation and invalid grammar passed",
}, indent=2) + "\n")
